		at = plume.obj.luaMacro("at", function (args)
			local __name      = "at"
			local __signature = "`$at(table t, number index, [number stop])`"
			local __s, __e, self, t, index, stop
			__s, __e, t, index, stop = plume.stdUnpackPositional(args, 2, 3,  __name, __signature)
			if __s then __s, __e, self = plume.stdUnpackNamed(args, {"self"}, __name, __signature) end
			if __s and t then __s, __e, t = plume.stdCheckType(t, "table", "1", __name, __signature) end
			if __s and index then __s, __e, index = plume.stdCheckType(index, "number", "2", __name, __signature) end
			if __s and stop then __s, __e, stop = plume.stdCheckType(stop, "number", "3", __name, __signature) end
			if not __s then return false, __e end
			------------
	
			index = handleNegativeIndex(index, #t.table)
			if stop then
				stop = handleNegativeIndex(stop, #t.table)
			end
	
			if stop then
				local result = plume.obj.table(stop - index + 1, 0)
				for i=index, stop do
					local value = t.table[i]
					if not value then
						return false, plume.error.unregisteredKey(t, index)
					end
					result:addItem(value)
				end
				return true, result
			else
				local value = t.table[index]
				if value then
					return true, value
				else
					return false, plume.error.unregisteredKey(t, index)
				end
			end
		end),
	
		setAt = plume.obj.luaMacro("setAt", function (args)
			local __name      = "setAt"
			local __signature = "`$setAt(table t, number index, any value)`"
			local __s, __e, self, t, index, value
			__s, __e, t, index, value = plume.stdUnpackPositional(args, 3, 3,  __name, __signature)
			if __s then __s, __e, self = plume.stdUnpackNamed(args, {"self"}, __name, __signature) end
			if __s and t then __s, __e, t = plume.stdCheckType(t, "table", "1", __name, __signature) end
			if __s and index then __s, __e, index = plume.stdCheckType(index, "number", "2", __name, __signature) end
			if not __s then return false, __e end
			------------
			index = handleNegativeIndex(index, #t.table)
	
			t:setItem(index, value)
			return true
		end),
	
		setMeta = plume.obj.luaMacro("setMeta", function (args)
			local __name      = "setMeta"
			local __signature = "`$setMeta(table t, table meta)`"
			local __s, __e, self, t, meta
			__s, __e, t, meta = plume.stdUnpackPositional(args, 2, 2,  __name, __signature)
			if __s then __s, __e, self = plume.stdUnpackNamed(args, {"self"}, __name, __signature) end
			if __s and t then __s, __e, t = plume.stdCheckType(t, "table", "1", __name, __signature) end
			if __s and meta then __s, __e, meta = plume.stdCheckType(meta, "table", "2", __name, __signature) end
			if not __s then return false, __e end
			------------
			t.meta = meta
			return true
		end),
		getMeta = plume.obj.luaMacro("setMeta", function (args)
			local __name      = "setMeta"
			local __signature = "`$setMeta(table t)`"
			local __s, __e, self, t
			__s, __e, t = plume.stdUnpackPositional(args, 1, 1,  __name, __signature)
			if __s then __s, __e, self = plume.stdUnpackNamed(args, {"self"}, __name, __signature) end
			if __s and t then __s, __e, t = plume.stdCheckType(t, "table", "1", __name, __signature) end
			if not __s then return false, __e end
			------------
			if not t.meta then
				t.meta = plume.obj.table(0, 0)
			end
	
			return true, t.meta
		end)
	}
	
	plume.std.Table.meta = plume.obj.quickTable{
		validate = plume.obj.luaMacro ("call", function (args)
			local __name      = "call"
			local __signature = "`$call(any x)`"
			local __s, __e, self, x
			__s, __e, x = plume.stdUnpackPositional(args, 1, 1,  __name, __signature)
			if __s then __s, __e, self = plume.stdUnpackNamed(args, {"self"}, __name, __signature) end
			if not __s then return false, __e end
			------------
			local t = type(x) == "table" and x.type or  type(x)
			if t ~= "table" then
				return false, string.format("Cannot convert '%s' to a table.", t)
			else
				return true, x
			end
		end)
	}
	
	local createDate, createDuration
	
	local function getType(x)
		return type(x) == "table" and x.table.type or type(x)
	end
	
	local function convert(t, v)
		local r
		if t == "number" or t == "string" and tonumber(v) then
			r = tonumber(v)
		elseif t == "Duration" then
			r = v.value
		elseif t == "Date" then
			r = v.table.timestamp
		else
			return false, string.format("Cannot do arithmetic on '%s' value.", t)
		end
	
		return true, r
	end
	
	local function sleep(s)
		local t = os.clock()
		while os.clock() - t <= s do end
	end
	
	local ddadd = plume.obj.luaMacro("add", function (args)
		local x = args.table[1]
		local y = args.table[2]
	
		local tx = getType(x)
		local ty = getType(y)
	
		local success, vx, vy
		
		success, vx = convert(tx, x)
		if not success then
			return success, vx
		end
		success, vy = convert(ty, y)
		if not success then
			return success, vy
		end
	
		local result = vx + vy
	
		if tx ~= "Date" and ty ~= "Date" then
			return createDuration(result)
		else
			return createDate({timestamp=result})
		end
	end)
	
	local ddsub = plume.obj.luaMacro("sub", function(args)
		local x = args.table[1]
		local y = args.table[2]
	
		local tx = getType(x)
		local ty = getType(y)
	
		local success, vx, vy
	
		success, vx = convert(tx, x)
		if not success then
			return success, vx
		end
		success, vy = convert(ty, y)
		if not success then
			return success, vy
		end
	
		local result = vx - vy
	
		if tx ~= "Date" and ty ~= "Date" then
			return createDuration(result)
		else
			return createDate({timestamp=result})
		end
	end)
	
	local ddmul = plume.obj.luaMacro("mul", function(args)
		local x = args.table[1]
		local y = args.table[2]
	
		local tx = getType(x)
		local ty = getType(y)
	
		if tx == "Date" or ty == "Date" then
			return false, "Cannot multiply a 'Date' value."
		end
	
		local success, vx, vy
	
		success, vx = convert(tx, x)
		if not success then
			return success, vx
		end
		success, vy = convert(ty, y)
		if not success then
			return success, vy
		end
	
		local result = vx * vy
	
		return createDuration(result)
	end)
	
	local dddiv = plume.obj.luaMacro("div", function(args)
		local x = args.table[1]
		local y = args.table[2]
	
		local tx = getType(x)
		local ty = getType(y)
	
		if tx == "Date" or ty == "Date" then
			return false, "Cannot divide a 'Date' value."
		end
	
		local success, vx, vy
	
		success, vx = convert(tx, x)
		if not success then
			return success, vx
		end
		success, vy = convert(ty, y)
		if not success then
			return success, vy
		end
	
		local result = vx / vy
	
		return createDuration(result)
	end)
	
	
	function createDate (args)
		local time = plume.obj.table(0, 0)
	
		function time:updateTimestamp(args)
			time:setItem("timestamp", os.time({
				year   = args.table.year or 1970,
				month  = args.table.month or 1,
				day    = args.table.day or 1,
				hour   = args.table.hour or 1,
				min    = args.table.minute or 0,
				sec    = args.table.second or 0
			}))
			if self.table.timestamp then
				return true
			else
				return false, "Cannot make a Date frome these parameters."
			end
		end
	
		function time:getFromTimestamp()
			local timestamp   = self.table.timestamp
			return {
				year   = tonumber(os.date("%Y", timestamp)),
				month  = tonumber(os.date("%m", timestamp)),
				day    = tonumber(os.date("%d", timestamp)),
				hour   = tonumber(os.date("%H", timestamp)),
				minute = tonumber(os.date("%M", timestamp)),
				second = tonumber(os.date("%S", timestamp))
			}
		end
	
		time:setItem("type", "Date")
	
		local success, result = true
		if args.timestamp and args.timestamp ~= 0 then
			time:setItem("timestamp", args.timestamp)
		else
			success, result = time:updateTimestamp(args)
		end
	
		if not success then
			return success, result
		end
	
		time.meta = plume.obj.quickTable{
			tostring = plume.obj.luaMacro ("tostring", function(args)
				local self = args.table.self
				return true, os.date("%x", self.table.timestamp)
			end),
			setindex = plume.obj.luaMacro ("setindex", function(args)
				local self   = args.table.self
				local key    = args.table[1]
				local value  = args.table[2]
				local values = self:getFromTimestamp()
	
				if not values[key] then
					return true, value
				end
	
				values[key] = value
				time:updateTimestamp(values)
	
				return true
			end),
			getindex = plume.obj.luaMacro ("getindex", function(args)
				local self = args.table.self
				local key = args.table[1]
				local values = self:getFromTimestamp()
	
				if not values[key] then
					return false, string.format("Unregistered key '%s'", key)
				end
				return true, values[key]
			end),
			add = ddadd,
			sub = ddsub,
			mul = ddmul,
			div = dddiv,
			eq = plume.obj.luaMacro("eq", function(args)
				local x = args.table[1]
				local y = args.table[2]
	
				local tx = getType(x)
				local ty = getType(y)
	
				if tx ~= "Date" or ty ~= "Date" then
					return true, false
				end
	
				return true, x.table.timestamp == y.table.timestamp
			end),
			lt = plume.obj.luaMacro("lt", function(args)
				local x = args.table[1]
				local y = args.table[2]
	
				local tx = getType(x)
				local ty = getType(y)
	
				if tx ~= "Date" or ty ~= "Date" then
					return false, string.format("Cannot compare 'Date' and '%s'", (tx ~= "Date" and tx or ty))
				end
	
				return true, x.table.timestamp < y.table.timestamp
			end)
		}
		
		return true, time
	end
	
	function createDuration(s)
		local duration = plume.obj.table(0, 0)
		duration.value = s
	
		duration.keys = {"type"}
	
		duration.table.type = "Duration"
	
		duration.meta = plume.obj.quickTable({
			tostring = plume.obj.luaMacro ("tostring", function(args)
				local self = args.table.self
				return true, self.value
			end),
			setindex = plume.obj.luaMacro ("setindex", function(args)
				return false, "Cannot edit 'duration' fields."
			end),
			getindex = plume.obj.luaMacro ("getindex", function(args)
				local self = args.table.self
				local key = args.table[1]
				
				if key == "day" then
					return true, self.value / 86400
				elseif key == "hour" then
					return true, self.value / 3600
				elseif key == "minute" then
					return true, self.value / 60
				elseif key == "second" then
					return true, self.value
				else
					return false, string.format("Unregistered key '%s'", key)
				end
			end),
	
			add = ddadd,
			sub = ddsub,
			mul = ddmul,
			div = dddiv,
	
			eq = plume.obj.luaMacro("eq", function(args)
				local x = args.table[1]
				local y = args.table[2]
	
				local tx = getType(x)
				local ty = getType(y)
	
				if tx ~= "Duration" or ty ~= "Duration" then
					return true, false
				end
	
				return true, x.value == y.value
			end),
	
			lt = plume.obj.luaMacro("lt", function(args)
				local x = args.table[1]
				local y = args.table[2]
	
				local tx = getType(x)
				local ty = getType(y)
	
				if tx ~= "Duration" or ty ~= "Duration" then
					return false, string.format("Cannot compare 'Duration' and '%s'", (tx ~= "Duration" and tx or ty))
				end
	
				return true, x.value < y.value
			end)
		})
	
		return true, duration
	end
	
	local function ignoreSuccess(_, y)
		return y
	end
	
	plume.std.Time = plume.obj.quickTable{
		date = plume.obj.luaMacro("date", function(args)
			local __name      = "add"
		local __signature = "`$add(number year: 1970, number month: 1, number day: 1, number hour: 1, number minute: 0, number second: 0, string zone:, string locale:, number timestamp: 0)`"
		local __s, __e, self = plume.stdUnpackPositional(args, 0, 0, __name, __signature)
		local year, month, day, hour, minute, second, zone, locale, timestamp
		if __s then __s, __e, self, year, month, day, hour, minute, second, zone, locale, timestamp = plume.stdUnpackNamed(args, {"self", "year", "month", "day", "hour", "minute", "second", "zone", "locale", "timestamp"}, __name, __signature) end
		year = year or nil
		month = month or nil
		day = day or nil
		hour = hour or nil
		minute = minute or nil
		second = second or nil
		zone = zone or nil
		locale = locale or nil
		timestamp = timestamp or nil
		if __s and year then __s, __e, year = plume.stdCheckType(year, "number", "year", __name, __signature) end
		if __s and month then __s, __e, month = plume.stdCheckType(month, "number", "month", __name, __signature) end
		if __s and day then __s, __e, day = plume.stdCheckType(day, "number", "day", __name, __signature) end
		if __s and hour then __s, __e, hour = plume.stdCheckType(hour, "number", "hour", __name, __signature) end
		if __s and minute then __s, __e, minute = plume.stdCheckType(minute, "number", "minute", __name, __signature) end
		if __s and second then __s, __e, second = plume.stdCheckType(second, "number", "second", __name, __signature) end
		if __s and zone then __s, __e, zone = plume.stdCheckType(zone, "string", "zone", __name, __signature) end
		if __s and locale then __s, __e, locale = plume.stdCheckType(locale, "string", "locale", __name, __signature) end
		if __s and timestamp then __s, __e, timestamp = plume.stdCheckType(timestamp, "number", "timestamp", __name, __signature) end
		if not __s then return false, __e end
		------------
			return createDate(args)
		end),
		
		duration = plume.obj.luaMacro("duration", function (args)
			local __name      = "duration"
			local __signature = "`$duration(number seconds)`"
			local __s, __e, self, seconds
			__s, __e, seconds = plume.stdUnpackPositional(args, 1, 1,  __name, __signature)
			if __s then __s, __e, self = plume.stdUnpackNamed(args, {"self"}, __name, __signature) end
			if __s and seconds then __s, __e, seconds = plume.stdCheckType(seconds, "number", "1", __name, __signature) end
			if not __s then return false, __e end
			------------
			return createDuration(seconds)
		end),
	
		now = plume.obj.luaMacro("now", function (args)
			local __name      = "now"
			local __signature = "`$now()`"
			local __s, __e, self = plume.stdUnpackPositional(args, 0, 0, __name, __signature)
			if __s then __s, __e, self = plume.stdUnpackNamed(args, {"self"}, __name, __signature) end
			if not __s then return false, __e end
			------------
			return createDate({timestamp=os.time()})
		end),
	
		SECOND = ignoreSuccess(createDuration(1)),
		MINUTE = ignoreSuccess(createDuration(60)),
		HOUR   = ignoreSuccess(createDuration(3600)),
		DAY    = ignoreSuccess(createDuration(86400)),
		WEEK   = ignoreSuccess(createDuration(604800)),
	
		sleep =  plume.obj.luaMacro("sleep", function (args)
			local __name      = "sleep"
			local __signature = "`$sleep(number|Duration s)`"
			local __s, __e, self, s
			__s, __e, s = plume.stdUnpackPositional(args, 1, 1,  __name, __signature)
			if __s then __s, __e, self = plume.stdUnpackNamed(args, {"self"}, __name, __signature) end
			if __s and s then
				__s, __e, s = plume.stdCheckType(s, "number", "1", __name, __signature)
				if not __s then
					__s, __e, s = plume.stdCheckType(s, "Duration", "1", __name, __signature)
				end
			end
			if not __s then return false, __e end
			------------
			if type(s) == "table" then
				s = s.value
			end
	
			sleep(s)
			return true
		end)
	}
	
	
	function plume.stdUnpackPositional (args, minArgs, maxArgs, name, signature)
		if #args.table < minArgs or #args.table > maxArgs then
			return false, plume.error.wrongArgsCountStd(
					name, #args.table, minArgs, maxArgs, signature
				)
		end
	
		return true, nil, unpack(args.table)
	end
	
	function plume.stdUnpackNamed(args, nameds, name, signature)
		local result = {}
	
		for _, key in ipairs(nameds) do
			nameds[key] = true
			if args.table[key] then
				table.insert(result, args.table[key])
			else
				table.insert(result, false)
			end
		end
	
		for _, key in ipairs(args.keys) do
			if not tonumber(key) then
				if nameds and nameds[key] then
					table.insert(result, args.table[key])
				else
					return false, plume.error.unknownParameterStd(key, name, signature)
				end
			end
		end
	
	
		return true, nil, unpack(result)
	end
	
	function plume.stdCheckType(arg, expected, argName, name, signature)
		local given = type(arg)
		if type(arg) == "table" and arg.type then
			if expected ~= "table" and arg.subtype then
				given = arg.subtype
			elseif expected ~= "table" and arg.table and arg.table.type then
				given = arg.table.type
			else
				given = arg.type
			end
		end
		if given == "luaMacro" or given == "stdMacro" or given == "closure" then
			given = "macro"
		end
	
		if given == "string" and expected == "number" then
			if tonumber(arg) then
				arg = tonumber(arg)
				given = "number"
			end
		elseif given == "number" and expected == "string" then
			arg = tostring(arg)
			given = "string"
		end
	
		if given == expected then
			return true, nil, arg
		else
			return false, plume.error.wrongArgTypeStd(
				argName, name, given, expected, signature
			), arg
		end
	end
	
	plume.stdVM = {}
	local function registerLuaStdFunction(name, minArgs, maxArgs)
		if not minArgs then
			minArgs = 0
		end
		if not maxArgs then
			maxArgs = minArgs
		end
	
		plume.stdVM[name] = {
			type = "stdMacro",
			name = name,
			opcode = plume.ops_count,
			minArgs = minArgs,
			maxArgs = maxArgs
		}
		
		local opName = "STD_" .. name:upper()
		plume.ops[opName] = plume.ops_count
		plume.ops_names = plume.ops_names .. " " .. opName
		plume.ops_count = plume.ops_count + 1
	
	end
	
	registerLuaStdFunction("len", 1)
	registerLuaStdFunction("type", 1)
	registerLuaStdFunction("seq", 1, 3)
	registerLuaStdFunction("items", 1)
	registerLuaStdFunction("enumerate", 1)
	registerLuaStdFunction("import", 1)
	
	for name, obj in pairs(plume.stdVM) do
		plume.std[name] = obj
	end
end
